const MOUSE_SENSITIVITY: f32 = 0.0022;
const TICK: Duration = Duration::from_millis(50);
const PLAYER_STATE_SAVE_INTERVAL: Duration = Duration::from_secs(15);
/// Vanilla's `PlayerControllerMP.getBlockReachDistance`.
const REACH_CREATIVE: f64 = 5.0;
const REACH_SURVIVAL: f64 = 4.5;
/// How far `C02 Use Entity` may reach.
///
/// The server validates an attack against the victim's bounding box plus a
/// 0.1 block cushion and silently drops anything beyond 3.0, so aiming further
/// only produces hits that never register.
const ENTITY_REACH: f64 = 3.0;
/// Minimum gap between entity attacks while the left button is held.
const ENTITY_ATTACK_INTERVAL: Duration = Duration::from_millis(250);
/// Selection outline colour, matching vanilla's black wireframe.
const OUTLINE_COLOR: [f32; 3] = [0.0, 0.0, 0.0];
/// How long a status ping may take before the row is shown as offline.
const PING_TIMEOUT: Duration = Duration::from_secs(1);
/// Two clicks on the same server within this window join it (`double-click`).
const DOUBLE_CLICK: Duration = Duration::from_millis(400);
/// Smooth streaming: meshes are uploaded over several frames instead of all in
/// the frame they finish. This bounds the driver-side copy at ~2 MiB/frame.
const CHUNK_UPLOAD_BUDGET_BYTES: usize = 2 * 1024 * 1024;
const CHUNK_UPLOAD_BUDGET_COUNT: usize = 12;

pub struct PlayOptions {
    /// None opens the title screen instead of connecting straight away.
    pub address: Option<ServerAddress>,
    pub username: String,
    pub assets_dir: std::path::PathBuf,
    pub fly: bool,
    /// Single-player world seed; random when absent.
    pub seed: Option<u64>,
    /// Sign in with the cached Microsoft session instead of connecting offline.
    pub online: bool,
    /// Where the cached session lives.
    pub session_path: std::path::PathBuf,
    /// Where the saved multiplayer list lives.
    pub servers_path: std::path::PathBuf,
}

enum NetMsg {
    Chunks(Vec<ChunkColumn>),
    Unload(i32, i32),
    /// The client world was rebuilt for another dimension. Everything the
    /// renderer cached is keyed by chunk coordinate, and those coordinates are
    /// reused, so the whole cache has to go.
    WorldReset {
        dimension: i8,
    },
    Chat(String),
    /// The full entity table, replaced wholesale. Cheap enough at 20 Hz.
    Entities(Vec<EntitySnapshot>),
    /// Tab-list skin hashes (uuid, texture hash).
    Skins(Vec<([u8; 16], String)>),
    /// A block was destroyed (or placed) near the player; throw debris.
    BlockEffect {
        x: i32,
        y: i32,
        z: i32,
        state: u16,
    },
    /// A note block played; `pitch` is its note (0..=24).
    NoteBlock {
        x: i32,
        y: i32,
        z: i32,
        pitch: u8,
    },
    Error(String),
}

/// One finished server-list ping, sent from its worker thread.
struct PingReply {
    address: String,
    ping: Ping,
}

/// One tracked entity, copied out of the client so the render thread can
/// interpolate it without touching the network thread's state.
#[derive(Debug, Clone, Copy)]
struct EntitySnapshot {
    player: bool,
    uuid: [u8; 16],
    /// Interpolation start and latest server position.
    prev: [f64; 3],
    position: [f64; 3],
    prev_yaw: f32,
    yaw: f32,
    head_yaw: f32,
    prev_head_yaw: f32,
    pitch: f32,
    /// Mob type, used to tint non-player entities.
    kind: u8,
    /// Item id and metadata for a dropped stack, `None` for players and mobs.
    item: Option<(i16, i16)>,
}

impl EntitySnapshot {
    fn from_entity(entity: &nephele_client::Entity) -> Option<Self> {
        let (player, uuid, kind) = match &entity.kind {
            nephele_client::EntityKind::Player { uuid, .. } => (true, *uuid, 0),
            nephele_client::EntityKind::Mob { kind } => (false, [0; 16], *kind),
            nephele_client::EntityKind::Item { .. } => (false, [0; 16], 0),
            // Item frames are parsed and tracked for the renderer that will
            // consume them; nothing draws them yet, so they stay out of the
            // snapshot rather than showing up as a tinted box.
            nephele_client::EntityKind::ItemFrame { .. } => return None,
        };
        let item = match entity.kind {
            nephele_client::EntityKind::Item { id, meta } => Some((id, meta)),
            _ => None,
        };
        Some(Self {
            player,
            uuid,
            prev: entity.prev,
            position: entity.position,
            prev_yaw: entity.prev_yaw,
            yaw: entity.yaw,
            head_yaw: entity.head_yaw,
            prev_head_yaw: entity.prev_head_yaw,
            pitch: entity.pitch,
            kind,
            item,
        })
    }
}

struct Shared {
    player: PlayerState,
    yaw: f32,
    pitch: f32,
    input: Input,
    status: String,
    spawned: bool,
    error: Option<String>,
    /// Left mouse button held.
    attacking: bool,
    /// Right click queued; the network thread consumes and clears it.
    use_pressed: bool,
    /// The player pressed the bound Drop Item key; both loops consume it.
    drop_item: bool,
    /// Hotbar slot the player just selected.
    pending_slot: Option<i16>,
    /// Set by the death screen, drained by the network loop.
    pending_respawn: bool,
    pack_offer: Option<String>,
    pack_choice: Option<(String, bool)>,
    /// Written by the network thread, read by the renderer.
    aim: Option<Aim>,
    break_stage: Option<u8>,
    held_slot: i16,
    creative: bool,
    /// Mirror of the 45-slot player container, for the hotbar.
    inventory: Vec<Option<ItemStack>>,
    health: f32,
    food: i32,
    food_saturation: f32,
    food_exhaustion: f32,
    xp_bar: f32,
    xp_level: i32,
    xp_total: i32,
    xp_seed: i32,
    /// World time in ticks (0..24000), used by the sky.
    time_of_day: f32,
    /// Bed spawn saved in `level.dat`, preserved across sessions.
    spawn_point: Option<[i32; 3]>,
    raining: bool,
    thundering: bool,
    /// Lightning flash strength, decayed by the render thread.
    lightning: f32,
    chunks: usize,
    /// Requested by the creative inventory, applied by the network thread.
    give_item: Option<(i16, ItemStack)>,
    /// Chat lines typed by the player; the game thread sends them on.
    chat_out: Vec<String>,
    /// `/setblock` requests, applied to the game thread's own world copy.
    world_edits: Vec<(i32, i32, i32, u16)>,
    /// `/gamemode` requests; `true` is creative.
    creative_override: Option<bool>,
    /// Container clicks from the inventory screen; the game thread sends them.
    inventory_clicks: Vec<(i16, i8, i8, Option<ItemStack>)>,
    /// Slots of the server's open container (crafting table), and whether one is.
    window_slots: Vec<Option<ItemStack>>,
    window_open: bool,
    /// `S2D` inventory type of the open window, for the panel title.
    window_kind: Option<String>,
    /// Our own tab-list latency, `None` until the server tells us.
    ping: Option<i32>,
    /// Entity under the crosshair, as picked by the network thread.
    target: Option<i32>,
    /// Server window id, or 1 for the local crafting-table window.
    window_id: Option<u8>,
    /// Offline crafting-table grid and cursor; the player's inventory stays above.
    local_container: LocalContainer,
    /// Ask the game thread to send `C0D` for the open container.
    close_window: bool,
    /// Single-player has no server to apply clicks, so the UI applies them.
    local: bool,
    /// The local simulation thread persists pending player state before stopping.
    local_shutdown: bool,
    local_stopped: bool,
    /// Render distance, pushed to the server as a client-settings update.
    view_distance: u8,
    /// Position at the start of the current tick, and when that tick began, so
    /// the renderer can interpolate between 20 Hz physics ticks.
    prev_position: [f64; 3],
    tick_at: Instant,
    /// Sound playback. `None` when there is no audio device, no prepared
    /// sounds, or `NEPHELE_MUTE` is set; every caller tolerates that.
    audio: Option<AudioEngine>,
}

fn refresh_local_crafting_preview(state: &mut Shared) {
    if !state.local {
        return;
    }
    if state.window_id == Some(1) {
        sync_local_table_inventory(state);
    } else {
        let result = inventory::player_crafting_result(&state.inventory);
        if let Some(slot) = state.inventory.first_mut() {
            *slot = result;
        }
    }
}

fn sync_local_table_inventory(state: &mut Shared) {
    if state.window_id != Some(1) || state.window_slots.len() < 46 {
        return;
    }
    state.window_slots[1..10].copy_from_slice(state.local_container.grid());
    state.window_slots[0] = inventory::table_crafting_result(&state.window_slots);
    state.window_slots[10..46].copy_from_slice(&state.inventory[9..45]);
}

fn open_local_crafting_table(state: &mut Shared) {
    state.local_container = LocalContainer::default();
    state.window_slots = vec![None; 46];
    state.window_id = Some(1);
    state.window_open = true;
    sync_local_table_inventory(state);
}

fn insert_player_stack(slots: &mut [Option<ItemStack>], item: ItemStack) -> Option<ItemStack> {
    let item = inventory::insert_stack(&mut slots[36..45], item)?;
    inventory::insert_stack(&mut slots[9..36], item)
}

fn local_block_drop(block: BlockState) -> Option<ItemStack> {
    let (id, meta) = match block.id() {
        0 | 7 | 8..=11 | 18 | 51 | 90 => return None,
        1 => (4, 0),                  // Stone drops cobblestone.
        2 => (3, 0),                  // Grass blocks drop dirt.
        17 => (17, block.meta() & 3), // The log axis is not item metadata.
        id => (id, block.meta()),
    };
    Some(ItemStack::new(id as i16, 1, meta as i16))
}

fn add_local_item(state: &mut Shared, item: ItemStack) {
    let Some(item) = inventory::insert_stack(&mut state.inventory[36..45], item) else {
        return;
    };
    let _ = inventory::insert_stack(&mut state.inventory[9..36], item);
}

fn consume_held_block(state: &mut Shared, slot: usize, block_state: u16) {
    let Some(item) = state.inventory.get_mut(slot).and_then(Option::as_mut) else {
        return;
    };
    if item.block_state() != Some(block_state) {
        return;
    }
    item.count -= 1;
    let empty = item.count <= 0;
    if empty {
        state.inventory[slot] = None;
    }
}

fn take_local_crafting_output(state: &mut Shared, cursor: &mut Option<ItemStack>) {
    let result = inventory::player_crafting_result(&state.inventory);
    let Some(result) = result else {
        return;
    };
    if !inventory::take_crafting_result(cursor, result) {
        return;
    }

    inventory::consume_crafting_grid(&mut state.inventory[1..5]);
    refresh_local_crafting_preview(state);
}

fn shift_craft_local_outputs(state: &mut Shared) {
    if state.window_id == Some(1) {
        for _ in 0..64 {
            let mut container = state.local_container.clone();
            let Some(result) = container.click(0, 0, true) else {
                break;
            };

            let mut inventory = state.inventory.clone();
            if insert_player_stack(&mut inventory, result).is_some() {
                break;
            }
            state.local_container = container;
            state.inventory = inventory;
        }
        refresh_local_crafting_preview(state);
        return;
    }

    for _ in 0..64 {
        let result = inventory::player_crafting_result(&state.inventory);
        let Some(result) = result else {
            break;
        };

        let mut inventory = state.inventory.clone();
        if insert_player_stack(&mut inventory, result).is_some() {
            break;
        }
        state.inventory = inventory;
        inventory::consume_crafting_grid(&mut state.inventory[1..5]);
    }
    refresh_local_crafting_preview(state);
}

pub fn run(options: PlayOptions) -> Result<(), Box<dyn Error>> {
    perf::start();
    let settings = initial_settings();
    let shared = Arc::new(Mutex::new(Shared {
        audio: start_audio(),
        view_distance: configured_view_distance(&settings),
        ..Shared::default()
    }));

    let (tx, rx) = mpsc::channel::<NetMsg>();

    let event_loop = EventLoop::new()?;
    event_loop.set_control_flow(ControlFlow::Poll);
    let mut app = LiveApp::new(options, shared, rx, tx, settings);
    event_loop.run_app(&mut app)?;
    match app.error.take() {
        Some(err) => Err(err),
        None => Ok(()),
    }
}

